import { elements } from 'tosijs';
/*#
# trackDrag

Sometimes you want to track a mouse-drag or touch-drag operation without messing around.
This is how the resizeable columns in `<tosi-table>` work.

Just call `trackDrag(event, (dx, dy, event) => { ... })` and you'll get updates on corresponding events until
you return `true` from the event-handler (or, in the case of `touch` events, the last `touch` ends).
For mouse events, a "tracker" element is thrown up in front of everything for the event.

```html
<p>
  Try dragging the squares…<br>
  (You can drag them separately with multi-touch!)
</p>
<div class="draggable" style="top: 20px; left: 40px; background: #f008"></div>
<div class="draggable" style="left: 40%; bottom: 30%; background: #0f08"></div>
<div class="draggable" style="bottom: 30px; right: 10px; background: #00f8"></div>
```
```css
.preview {
  touch-action: none;
}

.draggable {
  content: ' ';
  position: absolute;
  width: 50px;
  height: 50px;
  cursor: move;
}

.preview p {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translateX(-50%) translateY(-50%);
}
```
```js
import { trackDrag } from 'tosijs-ui'

function dragItem(event) {
  const draggable = event.target
  if (draggable.classList.contains('draggable')) {
    const x = draggable.offsetLeft
    const y = draggable.offsetTop
    trackDrag(event, (dx, dy, event) => {
      draggable.style.left = (x + dx) + 'px'
      draggable.style.top = (y + dy) + 'px'
      draggable.style.bottom = 'auto'
      draggable.style.right = 'auto'
      return event.type === 'mouseup'
    })
  }
}

preview.addEventListener('mousedown', dragItem )
preview.addEventListener('touchstart', dragItem, { passive: true } )
```

For `touch` events, `dx` and `dy` are based on tracking `event.changedTouches[0]` which
is almost certainly what you want.

To handle multi-touch gestures you will need to track the touches yourself.

## Do not register your `mousedown` listener as `passive`

Note the example above: `mousedown` is added **without** options, `touchstart` **with**
`{ passive: true }`. That asymmetry is load-bearing, not an oversight.

`trackDrag` calls `preventDefault()` on the mousedown that starts a drag, and **a passive
listener makes that a silent no-op** — no error, no warning, it simply does nothing. Without it,
Firefox treats the first drag on a freshly-loaded page as a text selection: what you grabbed
stays put, text highlights instead, and it only behaves after you have clicked somewhere to
settle Firefox's selection state. Landing on a page and immediately dragging something is an
entirely ordinary thing to do, so in practice the first attempt fails.

This bit every draggable in this library — `<tosi-sizer>`, `<tosi-float>`,
`<tosi-editable-rect>` and `<tosi-table>`'s column resize — from v0.5.1 until 1.12.2. Three of
them had passive `mousedown` listeners, so fixing `trackDrag` alone changed nothing for them;
`<tosi-table>`, whose listener was never passive, was fixed by the same change. If you use
`trackDrag` in your own component and dragging misbehaves on Firefox, this is the first thing
to check.

Nothing is lost by dropping `passive` on `mousedown`. Its practical value is silencing the
console warning about handlers that delay scrolling, and that warning only ever applied to
`touch` and `wheel` — keep it on `touchstart`, where `trackDrag` handles the equivalent on
`touchmove`.

## bringToFront

`bringToFront(element: HTMLElement, selector = 'body *')`  gives the element the highest
`z-index` of any element matching the selector (which is passed to findHighestZ).

## findHighestZ

`findHighestZ(selector = 'body *'): number` returns the the highest `z-index` of any element
matching `selector`.
*/
/*{ "parent": "Helper Libraries" }*/
const TRACKER = elements.div({
    style: {
        content: ' ',
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
    },
});
const PASSIVE = { passive: true };
export const trackDrag = (event, callback, cursor = 'move') => {
    const isTouchEvent = event.type.startsWith('touch');
    if (!isTouchEvent) {
        /*
        Stop the browser starting a TEXT SELECTION out of this mousedown.
    
        Firefox otherwise treats the first drag on a freshly-loaded page as a selection gesture: the
        thing you grabbed does not move, random text highlights instead, and the drag only starts
        behaving once you have clicked somewhere — anywhere — to settle Firefox's selection state.
        Land on a page and drag a column edge, which is an entirely ordinary thing to do, and the
        first attempt fails. Measured across `trackDrag`'s consumers with no prior click:
        `<tosi-sizer>` did not move at all, and a `<tosi-table>` column applied one 12px step and
        froze. Chromium and webkit were unaffected. It has been this way since the TRACKER overlay
        landed in v0.5.1.
    
        `preventDefault` here is narrow, not blunt, and that is why it is the right place for it:
        `trackDrag` is only ever called by a component that has ALREADY decided a drag is starting —
        the pointer is on a column boundary, a sizer, a float's handle. It is not attached to
        mousedown generally, so ordinary clicks, focus and text selection everywhere else are
        untouched.
    
        It only works if the caller's `mousedown` listener is NOT passive — a passive listener makes
        `preventDefault` a silent no-op, which is why `<tosi-sizer>`, `<tosi-float>` and
        `<tosi-editable-rect>` had to drop `PASSIVE` from theirs. Nothing is lost by that: passive's
        practical value is silencing the console warning about handlers that delay scrolling, and
        that warning only ever applied to touch and wheel.
    
        The touch branch below already does the equivalent on `touchmove`.
        */
        event.preventDefault();
        const origX = event.clientX;
        const origY = event.clientY;
        TRACKER.style.cursor = cursor;
        bringToFront(TRACKER);
        document.body.append(TRACKER);
        const wrappedCallback = (event) => {
            const dx = event.clientX - origX;
            const dy = event.clientY - origY;
            if (callback(dx, dy, event) === true) {
                TRACKER.removeEventListener('mousemove', wrappedCallback);
                TRACKER.removeEventListener('mouseup', wrappedCallback);
                TRACKER.remove();
            }
        };
        TRACKER.addEventListener('mousemove', wrappedCallback, PASSIVE);
        TRACKER.addEventListener('mouseup', wrappedCallback, PASSIVE);
    }
    else if (event instanceof TouchEvent) {
        const touch = event.changedTouches[0];
        const touchId = touch.identifier;
        const origX = touch.clientX;
        const origY = touch.clientY;
        const target = event.target;
        let dx = 0;
        let dy = 0;
        const wrappedCallback = (event) => {
            const touch = [...event.touches].find((touch) => touch.identifier === touchId);
            if (touch !== undefined) {
                dx = touch.clientX - origX;
                dy = touch.clientY - origY;
            }
            if (event.type === 'touchmove') {
                event.stopPropagation();
                event.preventDefault();
            }
            if (callback(dx, dy, event) === true || touch === undefined) {
                target.removeEventListener('touchmove', wrappedCallback);
                target.removeEventListener('touchend', wrappedCallback);
                target.removeEventListener('touchcancel', wrappedCallback);
            }
        };
        target.addEventListener('touchmove', wrappedCallback);
        target.addEventListener('touchend', wrappedCallback, PASSIVE);
        target.addEventListener('touchcancel', wrappedCallback, PASSIVE);
    }
};
export const findHighestZ = (selector = 'body *') => [...document.querySelectorAll(selector)]
    .map((elt) => parseFloat(getComputedStyle(elt).zIndex))
    .reduce((z, highest) => (isNaN(z) || Number(z) < highest ? highest : Number(z)), 0);
export const bringToFront = (element, selector = 'body *') => {
    element.style.zIndex = String(findHighestZ(selector) + 1);
};
